import{_ as t,o as a,c as i,a6 as n}from"./chunks/framework.BBdhcoHf.js";const m=JSON.parse('{"title":"Session Lifecycle","description":"","frontmatter":{},"headers":[],"relativePath":"runtime/session.md","filePath":"runtime/session.md","lastUpdated":1771970963000}'),r={name:"runtime/session.md"};function o(s,e,d,c,l,h){return a(),i("div",null,[...e[0]||(e[0]=[n(`<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /runtime/session.md for this page in Markdown format</div><h1 id="session-lifecycle" tabindex="-1">Session Lifecycle <a class="header-anchor" href="#session-lifecycle" aria-label="Permalink to “Session Lifecycle”">​</a></h1><blockquote><p><strong>Authority</strong>: Primary (Behavioral) <strong>Purpose</strong>: Normative behavioral contract for session lifecycle, negotiators, retry policy, and termination ordering. <strong>Status: Stub</strong> — Normative content is captured in <a href="./../adr/009-runtime-peer-lifecycle">ADR-009</a> pending promotion to this document.</p></blockquote><h2 id="layer-boundary" tabindex="-1">Layer Boundary <a class="header-anchor" href="#layer-boundary" aria-label="Permalink to “Layer Boundary”">​</a></h2><p>Session management sits between the transport (raw bytes) and the router (frame dispatch). It is responsible for negotiation, encryption wrapping, and lifecycle state — never for message routing or handler registration.</p><table tabindex="0"><thead><tr><th>Layer</th><th>Responsibility</th><th>Does NOT handle</th></tr></thead><tbody><tr><td>Transport</td><td>Connection, byte streams</td><td>Framing, security, routing</td></tr><tr><td>Session</td><td>Negotiation, encryption, session state</td><td>Message dispatch, handlers</td></tr><tr><td>Router</td><td>Handler registry, dispatch, correlation</td><td>Connection management</td></tr></tbody></table><h2 id="state-machine" tabindex="-1">State Machine <a class="header-anchor" href="#state-machine" aria-label="Permalink to “State Machine”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Idle → Connecting → Negotiating → Active ⇄ RetryWait</span></span>
<span class="line"><span>                                 └──────────────────→ Idle (fatal / terminate())</span></span></code></pre></div><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th></tr></thead><tbody><tr><td><code>Idle</code></td><td>No session. Initial and terminal state.</td></tr><tr><td><code>Connecting</code></td><td>Transport <code>connect()</code> in progress.</td></tr><tr><td><code>Negotiating</code></td><td>Transport open; negotiator establishing channel.</td></tr><tr><td><code>Active</code></td><td>Ready for message exchange.</td></tr><tr><td><code>RetryWait</code></td><td>Waiting before retry attempt (retry must be enabled).</td></tr></tbody></table><h2 id="invariants" tabindex="-1">Invariants <a class="header-anchor" href="#invariants" aria-label="Permalink to “Invariants”">​</a></h2><ul><li>At most one <code>Session</code> may be <code>Active</code> per <code>Peer</code> in v1.</li><li><code>terminate()</code> MUST be idempotent and cancel pending retries.</li><li>On retry, the existing session is replaced; retries never create parallel sessions.</li><li>When a <code>SessionChannel</code> distinct from the transport is present, the runtime MUST close the channel before closing the transport.</li><li>Negotiators MUST classify <code>ProtocolViolation</code> and <code>UnsupportedVersion</code> as fatal per SBP spec.</li><li>Session <code>state</code> is observable; application code SHOULD NOT branch on internal states — use events instead.</li></ul><h2 id="full-specification" tabindex="-1">Full Specification <a class="header-anchor" href="#full-specification" aria-label="Permalink to “Full Specification”">​</a></h2><p>See <a href="./../adr/009-runtime-peer-lifecycle">ADR-009</a> for the complete normative spec including the <code>Negotiator</code> interface, <code>RetryPolicy</code>, <code>SessionEvents</code>, and termination ordering.</p>`,13)])])}const g=t(r,[["render",o]]);export{m as __pageData,g as default};
